class Solution {
public:
    vector<int> powerfulIntegers(int x, int y, int bound) {
        vector<int> px = {1};
        if (x > 1) {
            while ((long long)px.back() * x < bound) {
                px.push_back(px.back() * x);
            }
        }
        vector<int> py = {1};
        if (y > 1) {
            while ((long long)py.back() * y < bound) {
                py.push_back(py.back() * y);
            }
        }
        set<int> res;
        for (int a : px) {
            for (int b : py) {
                if (a + b <= bound) res.insert(a + b);
            }
        }
        return vector<int>(res.begin(), res.end());
    }
};

class Solution {
    public List<Integer> powerfulIntegers(int x, int y, int bound) {
        List<Integer> px = new ArrayList<>();
        px.add(1);
        if (x > 1) {
            while ((long) px.get(px.size() - 1) * x < bound) {
                px.add(px.get(px.size() - 1) * x);
            }
        }
        List<Integer> py = new ArrayList<>();
        py.add(1);
        if (y > 1) {
            while ((long) py.get(py.size() - 1) * y < bound) {
                py.add(py.get(py.size() - 1) * y);
            }
        }
        Set<Integer> res = new TreeSet<>();
        for (int a : px) {
            for (int b : py) {
                if (a + b <= bound) res.add(a + b);
            }
        }
        return new ArrayList<>(res);
    }
}

var powerfulIntegers = function(x, y, bound) {
    const px = [1];
    if (x > 1) {
        while (px[px.length - 1] * x < bound) {
            px.push(px[px.length - 1] * x);
        }
    }
    const py = [1];
    if (y > 1) {
        while (py[py.length - 1] * y < bound) {
            py.push(py[py.length - 1] * y);
        }
    }
    const res = new Set();
    for (const a of px) {
        for (const b of py) {
            if (a + b <= bound) res.add(a + b);
        }
    }
    return Array.from(res).sort((a, b) => a - b);
};
